import {
	Component,
	Element,
	Event,
	EventEmitter,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import FormControl from "../../functional-components/form-control/form-control";
import { attachElementInternals } from "../../utils/element-internals";
import { hasSlot } from "../../utils/slot";

let id = 0;
const DEFAULT_ROWS = 3;

/**
 * @since 0.0.10
 * @status stable
 *
 * @description Text Area component.
 *
 * @slot label - The textarea's label. Alternatively, you can use the label prop.
 * @slot label-suffix - Non-interactive content to display inline with the textarea label.
 * @slot label-info - Interactive informational content, such as a tooltip trigger, displayed next to the textarea label.
 * @slot help-text - Help text that describes how to use the input.
 *
 * @part base - The component's base wrapper.
 * @part form-control - The form control that wraps the label, textarea, and help text.
 * @part label-container - The container that wraps the label and label-info slot.
 * @part label - The textarea label.
 * @part textarea - The textarea control.
 * @part help-text - The textarea help text.
 */

@Component({
	tag: "hbr-textarea",
	styleUrl: "textarea.scss",
	shadow: true,
	formAssociated: true,
})
export class Textarea {
	inputId = `textarea-${++id}`;
	labelId = `textarea-label-${id}`;
	helpTextId = `textarea-help-text-${id}`;
	resizeObserver: ResizeObserver;
	textarea: HTMLTextAreaElement;

	@Element() host: HTMLHbrTextareaElement;

	private internals?: ElementInternals;

	@State() hasFocus = false;
	@State() hasHelpTextSlot = false;
	@State() hasLabelSlot = false;
	@State() hasLabelInfoSlot = false;
	@State() hasFrontSlot = false;
	@State() hasRearSlot = false;

	/** The textarea's size. */
	@Prop({ reflect: true }) size: "small" | "medium" | "large" = "medium";

	/** The textarea's name attribute. */
	@Prop({ reflect: true }) name = "";

	/** The textarea's value attribute. */
	@Prop({ mutable: true, reflect: true }) value = "";

	/** The textarea's label. Alternatively, you can use the label slot. */
	@Prop() label = "";

	/** The textarea's help text. Alternatively, you can use the help-text slot. */
	@Prop() helpText = "";

	/** The textarea's placeholder text. */
	@Prop() placeholder: string;

	/** Specifies the number of visible text rows. Defaults to 3 rows (80px height). */
	@Prop() rows = DEFAULT_ROWS;

	/** Controls how the textarea can be resized. */
	@Prop() resize: "none" | "vertical" | "auto" = "vertical";

	/** Set to true to disable the textarea. */
	@Prop({ reflect: true }) disabled = false;

	/** Set to true for a readonly textarea. */
	@Prop({ reflect: true }) readonly = false;

	/** The minimum length of input that will be considered valid. */
	@Prop({ reflect: true }) minlength: number;

	/** The maximum length of input that will be considered valid. */
	@Prop({ reflect: true }) maxlength: number;

	/** Show character counter. Default to display a character counter for text area inputs when a character limit is set.
	 * v2.14.5 */
	@Prop({ mutable: true }) counter = true;

	/** The textarea's required attribute. */
	@Prop({ reflect: true }) required: boolean;

	/**
	 * This will be true when the control is in an invalid state. Validity is determined by props such as `required`,
	 * `minlength`, and `maxlength` using the browser's constraint validation API.
	 */
	@Prop({ mutable: true, reflect: true }) invalid = false;

	/** The textarea's autocapitalize attribute. */
	@Prop() autocapitalize:
		| "off"
		| "none"
		| "on"
		| "sentences"
		| "words"
		| "characters";

	/** The textarea's autocorrect attribute. */
	@Prop() autocorrect: string;

	/** The textarea's autocomplete attribute. */
	@Prop() autocomplete: string;

	/** The textarea's autofocus attribute. */
	@Prop() autofocus: boolean;

	/** The textarea's spellcheck attribute. */
	@Prop() spellcheck: boolean;

	/** The textarea's inputmode attribute. */
	@Prop() inputmode:
		| "none"
		| "text"
		| "decimal"
		| "numeric"
		| "tel"
		| "search"
		| "email"
		| "url";

	/** Set style for error state */
	@Prop() error = false;

	/** aria-label When no label  is set */
	@Prop() arialabel: string;

	/** Emitted when the control's value changes. */
	@Event({ eventName: "hbr-change" }) hbrChange: EventEmitter;

	/** Emitted when the control receives input. */
	@Event({ eventName: "hbr-input" }) hbrInput: EventEmitter;

	/** Emitted when the control gains focus. */
	@Event({ eventName: "hbr-focus" }) hbrFocus: EventEmitter;

	/** Emitted when the control loses focus. */
	@Event({ eventName: "hbr-blur" }) hbrBlur: EventEmitter;

	@Watch("helpText")
	@Watch("label")
	handleLabelChange() {
		this.handleSlotChange();
	}

	@Watch("rows")
	handleRowsChange() {
		this.setTextareaHeight();
	}

	@Watch("disabled")
	handleDisabledChange() {
		// Disabled form controls are always valid, so we need to recheck validity when the state changes
		if (!this.textarea) {
			return;
		}
		this.textarea.disabled = this.disabled;
		this.invalid = !this.textarea.checkValidity();
	}

	@Watch("value")
	handleValueChange() {
		// In rare cases, the watcher may be called before render so we need to make sure the textarea exists
		this.invalid = this.textarea ? !this.textarea.checkValidity() : false;
		// When value updates, textArea height should be updated
		// setTimeout is used to make sure value is updated in textarea before height is calculated
		setTimeout(() => this.setTextareaHeight());
		this.internals?.setFormValue(this.value || null);
	}

	connectedCallback() {
		this.internals ??= attachElementInternals(this.host);
		this.handleChange = this.handleChange.bind(this);
		this.handleInput = this.handleInput.bind(this);
		this.handleBlur = this.handleBlur.bind(this);
		this.handleFocus = this.handleFocus.bind(this);
		this.handleSlotChange = this.handleSlotChange.bind(this);
		this.handleInvalid = this.handleInvalid.bind(this);
		this.handleValueChange = this.handleValueChange.bind(this);
		this.handleDisabledChange = this.handleDisabledChange.bind(this);
		this.renderHelpTextRight = this.renderHelpTextRight.bind(this);

		this.host.shadowRoot.addEventListener("slotchange", this.handleSlotChange);
	}

	componentWillLoad() {
		this.handleSlotChange();
	}

	componentDidLoad() {
		this.setTextareaHeight();
		this.resizeObserver = new ResizeObserver(() => this.setTextareaHeight());

		if (this.textarea) {
			this.resizeObserver.observe(this.textarea);
			this.invalid = !this.textarea.checkValidity();
		}
	}

	disconnectedCallback() {
		this.resizeObserver?.unobserve(this.textarea);
		this.host.shadowRoot.removeEventListener(
			"slotchange",
			this.handleSlotChange,
		);
	}

	/** Sets focus on the textarea. */
	@Method()
	async setFocus(options?: FocusOptions) {
		this.textarea.focus(options);
	}

	/** Removes focus from the textarea. */
	@Method()
	async removeFocus() {
		this.textarea.blur();
	}

	/** Selects all the text in the input. */
	@Method()
	async select() {
		return this.textarea?.select();
	}

	/** Sets the start and end positions of the text selection (0-based). */
	@Method()
	async setSelectionRange(
		selectionStart: number,
		selectionEnd: number,
		selectionDirection: "forward" | "backward" | "none" = "none",
	) {
		return this.textarea?.setSelectionRange(
			selectionStart,
			selectionEnd,
			selectionDirection,
		);
	}

	/** Replaces a range of text with a new string. */
	@Method()
	async setRangeText(
		replacement: string,
		start: number,
		end: number,
		selectMode: "select" | "start" | "end" | "preserve" = "preserve",
	) {
		if (this.textarea) {
			this.textarea.setRangeText(replacement, start, end, selectMode);

			if (this.value !== this.textarea.value) {
				this.value = this.textarea.value;
				this.setTextareaHeight();
				this.hbrChange.emit();
				this.hbrInput.emit();
			}
		}
	}

	/** Checks for validity and shows the browser's validation message if the control is invalid. */
	@Method()
	async reportValidity() {
		return this.textarea?.reportValidity();
	}

	/** Sets a custom validation message. If `message` is not empty, the field will be considered invalid. */
	@Method()
	async setCustomValidity(message: string) {
		if (this.textarea) {
			this.textarea.setCustomValidity(message);
			this.invalid = !this.textarea.checkValidity();
		}
	}

	/** Scrolls the textarea to the bottom. Useful for display where new content is appended. */
	@Method()
	async scrollToBottom() {
		if (!this.textarea) {
			return;
		}

		// Frameworks (Angular, React, Vue) often call scrollToBottom in the same
		// tick as updating state, but the new value prop hasn't been pushed to
		// the web component yet. Yielding to the next microtask lets the
		// framework's change-detection / render cycle flush the binding first.
		await Promise.resolve();

		if (!this.textarea) return;

		// Ensure the native element and auto-height are in sync with the
		// (now-updated) value before we measure scrollHeight.
		this.textarea.value = this.value;
		this.setTextareaHeight();

		this.textarea.scrollTop = this.textarea.scrollHeight;
	}

	handleChange() {
		this.hbrChange.emit();
	}

	handleInput() {
		this.value = this.textarea?.value;
		this.setTextareaHeight();
		this.hbrInput.emit();
	}

	handleBlur() {
		this.hasFocus = false;
		this.hbrBlur.emit();
	}

	handleFocus() {
		this.hasFocus = true;
		this.hbrFocus.emit();
	}

	handleSlotChange() {
		this.hasLabelSlot = hasSlot(this.host, "label");
		this.hasLabelInfoSlot = hasSlot(this.host, "label-info");
		this.hasHelpTextSlot = hasSlot(this.host, "help-text");
		this.hasFrontSlot = hasSlot(this.host, "front");
		this.hasRearSlot = hasSlot(this.host, "rear");
	}

	handleInvalid() {
		this.invalid = true;
	}

	setTextareaHeight() {
		if (!this.textarea) {
			return;
		}

		const wrapper = this.textarea.closest(".textarea");
		const wrapperStyle =
			wrapper instanceof HTMLElement ? getComputedStyle(wrapper) : undefined;
		const maxHeight = wrapperStyle
			? Number.parseFloat(wrapperStyle.maxHeight)
			: Number.NaN;
		const hasMaxHeight = Number.isFinite(maxHeight) && maxHeight > 0;
		const textareaStyle = getComputedStyle(this.textarea);
		const verticalChrome =
			textareaStyle.boxSizing === "border-box"
				? 0
				: Number.parseFloat(textareaStyle.paddingTop || "0") +
				  Number.parseFloat(textareaStyle.paddingBottom || "0") +
				  Number.parseFloat(textareaStyle.borderTopWidth || "0") +
				  Number.parseFloat(textareaStyle.borderBottomWidth || "0");
		const textareaMaxHeight = hasMaxHeight
			? Math.max(maxHeight - verticalChrome, 0)
			: Number.NaN;

		if (hasMaxHeight) {
			this.textarea.style.maxHeight = `${textareaMaxHeight}px`;
		} else {
			this.textarea.style.removeProperty("max-height");
		}

		if (this.resize === "auto") {
			this.textarea.style.height = "auto";
			const maxConstrainedHeight = hasMaxHeight
				? Math.min(this.textarea.scrollHeight, textareaMaxHeight)
				: this.textarea.scrollHeight;
			this.textarea.style.height = `${maxConstrainedHeight}px`;
			this.textarea.style.overflowY =
				hasMaxHeight && this.textarea.scrollHeight > textareaMaxHeight
					? "auto"
					: "hidden";
		} else {
			if (hasMaxHeight && this.textarea.offsetHeight > maxHeight) {
				this.textarea.style.height = `${textareaMaxHeight}px`;
			}
			this.textarea.style.removeProperty("overflow-y");
		}
	}

	renderHelpTextRight() {
		if (!this.counter || !this.maxlength || this.maxlength <= 0) {
			return null;
		}
		if (this.helpText) {
			return (
				<div part="help-text-right" class="help-text-right">
					<slot name="help-text-right" />
					{this.renderCounterText()}
				</div>
			);
		}
		return null;
	}

	renderCounterText() {
		return (
			<div
				part="char-counter"
				slot="char-counter"
				class="textarea__char-counter"
			>
				<span
					class={{
						"char-counter__current": true,
						"char-counter__valid":
							this.value?.length > 0 && this.value?.length <= this.maxlength,
					}}
				>
					{this.value?.length || 0}
				</span>
				/<span class="char-max-length">{this.maxlength}</span>
			</div>
		);
	}

	render() {
		return (
			<FormControl
				inputId={this.inputId}
				label={this.label}
				labelId={this.labelId}
				hasLabelSlot={this.hasLabelSlot}
				hasLabelInfoSlot={this.hasLabelInfoSlot}
				hasFrontSlot={this.hasFrontSlot}
				hasRearSlot={this.hasRearSlot}
				helpTextId={
					this.helpText || this.hasHelpTextSlot ? this.helpTextId : undefined
				}
				helpText={this.helpText}
				hasHelpTextSlot={this.hasHelpTextSlot}
				size={this.size}
				source={"textarea"}
				hasFocus={this.hasFocus}
				hasValue={this.value?.length > 0}
				hasError={this.error}
				isRequired={this.required}
				isDisabled={this.disabled}
				maxlength={this.maxlength}
				renderHelpTextRight={this.renderHelpTextRight}
			>
				<div
					part="base"
					class={{
						textarea: true,

						// Sizes
						"textarea--small": this.size === "small",
						"textarea--medium": this.size === "medium",
						"textarea--large": this.size === "large",

						// States
						"textarea--disabled": this.disabled,
						"textarea--readonly": this.readonly,
						"textarea--focused": this.hasFocus,
						"textarea--empty": this.value?.length === 0,
						"textarea--invalid": this.invalid,
						"textarea--error": this.error,

						// Modifiers
						"textarea--resize-none": this.resize === "none",
						"textarea--resize-vertical": this.resize === "vertical",
						"textarea--resize-auto": this.resize === "auto",
						"textarea--max-length": this.maxlength && this.maxlength > 0,
						"textarea--rows": this.rows !== DEFAULT_ROWS,
					}}
				>
					<span part="prefix" class="textarea__prefix">
						<slot name="prefix" />
					</span>
					<textarea
						part={`textarea${this.error ? " error" : ""}`}
						ref={(el) => {
							this.textarea = el;
						}}
						id={this.inputId}
						class="textarea__control"
						name={this.name}
						placeholder={this.placeholder}
						disabled={this.disabled}
						readOnly={this.readonly}
						rows={this.rows}
						minLength={this.minlength}
						maxLength={this.maxlength}
						value={this.value}
						autoCapitalize={this.autocapitalize}
						autoCorrect={this.autocorrect}
						spellcheck={this.spellcheck}
						required={this.required}
						inputMode={this.inputmode}
						onChange={this.handleChange}
						onInput={this.handleInput}
						onInvalid={this.handleInvalid}
						onFocus={this.handleFocus}
						onBlur={this.handleBlur}
						aria-label={this.arialabel}
						aria-describedby={
							this.helpText || this.hasHelpTextSlot
								? this.helpTextId
								: undefined
						}
					/>

					<span part="suffix" class="textarea__suffix">
						<slot name="suffix" />
					</span>
				</div>
				{!this.helpText &&
					this.maxlength !== undefined &&
					this.maxlength > 0 &&
					this.counter &&
					this.renderCounterText()}
			</FormControl>
		);
	}
}
